package org.redisson.transaction;

import io.netty.buffer.ByteBuf;
import org.junit.jupiter.api.Test;
import org.redisson.client.codec.Codec;
import org.redisson.command.CommandAsyncExecutor;
import org.redisson.config.NameMapper;
import org.redisson.connection.ServiceManager;
import org.redisson.transaction.operation.TransactionalOperation;
import org.mockito.stubbing.Answer;

import java.lang.reflect.Method;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicBoolean;

import static org.mockito.ArgumentMatchers.any;
import static org.mockito.ArgumentMatchers.anyString;
import static org.mockito.Mockito.*;

/**
 * Tests that RedissonTransactionalBucket.isEquals() properly releases ByteBuf objects.
 *
 * The bug: in the finally block, isEquals() calls readableBytes() instead of release(),
 * which means the encoded ByteBuf objects are never released, causing a memory leak.
 *
 * The correct implementation (e.g. BaseTransactionalSet.isEqual()) calls release().
 */
public class RedissonTransactionalBucketIsEqualsReleaseTest {

    @Test
    public void testIsEqualsReleasesByteBufs() throws Exception {
        // Setup mocks
        ServiceManager serviceManager = mock(ServiceManager.class);
        Codec codec = mock(Codec.class);
        when(serviceManager.getCodec(codec)).thenReturn(codec);

        NameMapper nameMapper = mock(NameMapper.class);
        when(nameMapper.map(anyString())).thenAnswer(inv -> inv.getArgument(0));
        when(serviceManager.getNameMapper()).thenReturn(nameMapper);

        CommandAsyncExecutor commandExecutor = mock(CommandAsyncExecutor.class);
        when(commandExecutor.getServiceManager()).thenReturn(serviceManager);

        // Create mock ByteBufs to track method calls
        ByteBuf mockValueBuf = mock(ByteBuf.class);
        ByteBuf mockOldValueBuf = mock(ByteBuf.class);

        // Stub commandExecutor.encode() to return our mock ByteBufs
        // First call returns mockValueBuf, second returns mockOldValueBuf
        AtomicBoolean firstCall = new AtomicBoolean(true);
        when(commandExecutor.encode(any(Codec.class), any())).thenAnswer((Answer<ByteBuf>) invocation -> {
            if (firstCall.getAndSet(false)) {
                return mockValueBuf;
            }
            return mockOldValueBuf;
        });

        List<TransactionalOperation> operations = new ArrayList<>();
        AtomicBoolean executed = new AtomicBoolean();

        RedissonTransactionalBucket<String> bucket = new RedissonTransactionalBucket<>(
            codec,
            commandExecutor,
            30000L,
            "test-bucket",
            operations,
            executed,
            "tx-001"
        );

        // Call the private isEquals method via reflection
        Method isEqualsMethod = RedissonTransactionalBucket.class
            .getDeclaredMethod("isEquals", Object.class, Object.class);
        isEqualsMethod.setAccessible(true);

        isEqualsMethod.invoke(bucket, "hello", "hello");

        // Verify: the correct behavior is that release() is called on both ByteBufs
        // The bug causes readableBytes() to be called instead, which does NOT release
        verify(mockValueBuf, times(1)).release();
        verify(mockOldValueBuf, times(1)).release();

        // Verify readableBytes() is NOT called (it should not be in the finally block)
        verify(mockValueBuf, never()).readableBytes();
        verify(mockOldValueBuf, never()).readableBytes();
    }

    @Test
    public void testIsEqualsReleasesByteBufsOnInequality() throws Exception {
        // Also test the case where values are NOT equal - buffers should still be released

        ServiceManager serviceManager = mock(ServiceManager.class);
        Codec codec = mock(Codec.class);
        when(serviceManager.getCodec(codec)).thenReturn(codec);

        NameMapper nameMapper = mock(NameMapper.class);
        when(nameMapper.map(anyString())).thenAnswer(inv -> inv.getArgument(0));
        when(serviceManager.getNameMapper()).thenReturn(nameMapper);

        CommandAsyncExecutor commandExecutor = mock(CommandAsyncExecutor.class);
        when(commandExecutor.getServiceManager()).thenReturn(serviceManager);

        ByteBuf mockValueBuf = mock(ByteBuf.class);
        ByteBuf mockOldValueBuf = mock(ByteBuf.class);

        AtomicBoolean firstCall = new AtomicBoolean(true);
        when(commandExecutor.encode(any(Codec.class), any())).thenAnswer((Answer<ByteBuf>) invocation -> {
            if (firstCall.getAndSet(false)) {
                return mockValueBuf;
            }
            return mockOldValueBuf;
        });

        List<TransactionalOperation> operations = new ArrayList<>();
        AtomicBoolean executed = new AtomicBoolean();

        RedissonTransactionalBucket<String> bucket = new RedissonTransactionalBucket<>(
            codec,
            commandExecutor,
            30000L,
            "test-bucket",
            operations,
            executed,
            "tx-002"
        );

        Method isEqualsMethod = RedissonTransactionalBucket.class
            .getDeclaredMethod("isEquals", Object.class, Object.class);
        isEqualsMethod.setAccessible(true);

        isEqualsMethod.invoke(bucket, "hello", "world");

        // Even when values differ, buffers must be released
        verify(mockValueBuf, times(1)).release();
        verify(mockOldValueBuf, times(1)).release();
    }
}

