package org.redisson;

import mockit.Expectations;
import mockit.Mocked;
import mockit.Tested;
import org.junit.jupiter.api.Test;
import org.redisson.api.MapOptions;
import org.redisson.api.RedissonClient;

import org.redisson.command.CommandAsyncExecutor;

import java.util.AbstractMap;
import java.util.Map;

import static org.assertj.core.api.Assertions.assertThat;

/**
 * Unit test for the bug in RedissonMap.EntrySet.contains(Object o).
 * 
 * The bug: line 1861 reads "return value != null && value.equals(e);"
 * where 'e' is a Map.Entry. It should compare with e.getValue(), not 'e'.
 * 
 * This test uses JMockit to mock all RedissonMap dependencies to avoid needing Docker/Redis.
 */
public class RedissonMapEntrySetContainsTest {

    @Mocked
    CommandAsyncExecutor commandExecutor;

    @Mocked
    RedissonClient redisson;

    @Mocked
    WriteBehindService writeBehindService;

    @Test
    public void testEntrySetContainsWithMatchingEntry() {
        RedissonMapSpy<String, String> map = new RedissonMapSpy<>(commandExecutor, redisson, writeBehindService);

        // Mock get() to return "value1" for key "key1"
        new Expectations() {{
            map.get("key1");
            result = "value1";
        }};

        Map.Entry<String, String> entry = new AbstractMap.SimpleEntry<>("key1", "value1");

        // The correct behavior: entrySet().contains(entry) should return true
        assertThat(map.entrySet().contains(entry)).isTrue();
    }

    @Test
    public void testEntrySetContainsWithWrongValue() {
        RedissonMapSpy<String, String> map = new RedissonMapSpy<>(commandExecutor, redisson, writeBehindService);

        new Expectations() {{
            map.get("key1");
            result = "value1";
        }};

        // Create an entry with matching key but wrong value
        Map.Entry<String, String> entry = new AbstractMap.SimpleEntry<>("key1", "wrong");

        // Should return false because the stored value is "value1", not "wrong"
        assertThat(map.entrySet().contains(entry)).isFalse();
    }

    @Test
    public void testEntrySetContainsWithWrongKey() {
        RedissonMapSpy<String, String> map = new RedissonMapSpy<>(commandExecutor, redisson, writeBehindService);

        new Expectations() {{
            map.get("wrong");
            result = null;
        }};

        // Create an entry with wrong key
        Map.Entry<String, String> entry = new AbstractMap.SimpleEntry<>("wrong", "value1");

        // Should return false because key "wrong" doesn't exist
        assertThat(map.entrySet().contains(entry)).isFalse();
    }

    @Test
    public void testEntrySetContainsWithNonEntryObject() {
        RedissonMapSpy<String, String> map = new RedissonMapSpy<>(commandExecutor, redisson, writeBehindService);

        // Should return false for non-Entry objects
        assertThat(map.entrySet().contains("not an entry")).isFalse();
    }

    /**
     * Minimal subclass of RedissonMap to allow construction without real Redis.
     */
    static class RedissonMapSpy<K, V> extends RedissonMap<K, V> {
        public RedissonMapSpy(CommandAsyncExecutor commandExecutor, 
                             RedissonClient redisson, 
                             WriteBehindService writeBehindService) {
            super(commandExecutor, "test", redisson, null, writeBehindService);
        }

        @Override
        public java.util.Set<Map.Entry<K, V>> entrySet() {
            return new EntrySet(null, 0);
        }
    }
}

